341	        walls.add("0,0,0,1");
342	        while(!walls.isEmpty()) {
343	            int index = random.nextInt(walls.size());
344	            String wall = walls.get(index);
345	            int fromRow = Integer.parseInt(wall.split(",")[0]);
346	            int fromCol = Integer.parseInt(wall.split(",")[1]);
347	            int toRow = Integer.parseInt(wall.split(",")[2]);
348	            int toCol = Integer.parseInt(wall.split(",")[3]);
