350	                if(toRow < fromRow) {
351	                    Main.mazeLabels[fromRow][fromCol].setUpAlready();
352	                    Main.mazeLabels[toRow][toCol].setDownAlready();
353	                }
354	                if(toRow > fromRow) {
355	                    Main.mazeLabels[fromRow][fromCol].setDownAlready();
356	                    Main.mazeLabels[toRow][toCol].setUpAlready();
357	                }
358	                if(toCol < fromCol) {
359	                    Main.mazeLabels[fromRow][fromCol].setLeftAlready();
360	                    Main.mazeLabels[toRow][toCol].setRightAlready();
361	                }
362	                if(toCol > fromCol) {
363	                    Main.mazeLabels[fromRow][fromCol].setRightAlready();
364	                    Main.mazeLabels[toRow][toCol].setLeftAlready();
365	                }
366	                row = toRow;
367	                col = toCol;
368	                Main.mazeLabels[row][col].setAlready();
369	                if(row >= 1) {
370	                    walls.add(row + "," + col + "," + String.valueOf(row - 1) + "," + col);
371	                }
372	                if(row <= 18) {
373	                    walls.add(row + "," + col + "," + String.valueOf(row + 1) + "," + col);
374	                }
375	                if(col >= 1) {
376	                    walls.add(row + "," + col + "," + row + "," + String.valueOf(col - 1));
377	                }
378	                if(col <= 23) {
379	                    walls.add(row + "," + col + "," + row + "," + String.valueOf(col + 1));
380	                }
381	            }
382	            else {
383	                walls.remove(index);
384	            }
385	        }
386	        Main.mazeLabels[19][24].setTarget();
387	        Main.mazeLabels[19][24].repaint();
388	        Main.mazeLabels[0][0].setCurrent();
389	        Main.mazeLabels[0][0].repaint();
390	    }
